sys_script.script:
(function runAITriageOnCaseInsert(current, previous) {

    // -----------------------------------------------------------------------
    // Guard: Only process if there is something useful for the LLM to read.
    // A case with no short_description AND no description gives the model
    // nothing to work with and wastes an LLM call.
    // -----------------------------------------------------------------------
    var hasDescription = !gs.nil(current.getValue('short_description')) ||
                         !gs.nil(current.getValue('description'));
    if (!hasDescription) {
        gs.info('x_2145749_qc AI Triage: Case ' + current.getUniqueValue() +
                ' has no description — skipping triage.');
        return;
    }

    // -----------------------------------------------------------------------
    // Call the engine
    // -----------------------------------------------------------------------
    var engine = new x_2145749_qc.CaseTriageEngine();
    var result = engine.triage(current);

    if (!result.success) {
        gs.error('x_2145749_qc AI Triage: Case ' + current.getUniqueValue() +
                 ' — triage failed: ' + result.error);
        // Even on failure we set needs_manual_review so agents know
        // the automation did not complete.
        var failGr = new GlideRecord('sn_customerservice_case');
        if (failGr.get(current.getUniqueValue())) {
            failGr.setValue('x_2145749_qc_needs_manual_review', true);
            failGr.setWorkflow(false);  // suppress further business rules on this update
            failGr.update();
        }
        return;
    }

    // -----------------------------------------------------------------------
    // Fetch the newly-inserted case record to apply updates.
    // We use a fresh GlideRecord rather than writing to current because
    // this Business Rule runs async (when=async) — current is the snapshot
    // at insert time, so updates must be persisted via a separate .update().
    // -----------------------------------------------------------------------
    var caseGr = new GlideRecord('sn_customerservice_case');
    if (!caseGr.get(current.getUniqueValue())) {
        gs.error('x_2145749_qc AI Triage: Could not retrieve Case ' +
                 current.getUniqueValue() + ' for write-back.');
        return;
    }

    var changed = false;

    // -----------------------------------------------------------------------
    // 3.3 — Always write the urgency score (AI assessment, not human input)
    // -----------------------------------------------------------------------
    if (result.urgency_score !== null) {
        caseGr.setValue('x_2145749_qc_ai_urgency_score', parseInt(result.urgency_score, 10));
        changed = true;
    }

    // -----------------------------------------------------------------------
    // 3.4 — Write complaint_type ONLY if it is currently empty.
    //        If a human already selected a category on the form, respect it.
    // -----------------------------------------------------------------------
    var existingCategory = caseGr.getValue('x_2145749_qc_complaint_type');
    if (gs.nil(existingCategory) && result.category) {
        caseGr.setValue('x_2145749_qc_complaint_type', result.category);
        changed = true;
    }

    // -----------------------------------------------------------------------
    // 3.5 — Set needs_manual_review flag when confidence is low.
    //        Only set to true; never clear a flag an agent may have set.
    // -----------------------------------------------------------------------
    if (result.needs_manual_review) {
        caseGr.setValue('x_2145749_qc_needs_manual_review', true);
        changed = true;
    }

    // -----------------------------------------------------------------------
    // Append a system work note summarising what the AI did, so agents have
    // full visibility.  This is appended, never overwritten.
    // -----------------------------------------------------------------------
    var noteLines = [
        '=== AI Triage (Order Complaint Triage Assistant) ===',
        'Suggested Category : ' + (result.category || 'n/a'),
        'Urgency Score      : ' + (result.urgency_score !== null ? result.urgency_score + ' / 10' : 'n/a'),
        'Manual Review Flag : ' + (result.needs_manual_review ? 'YES — ' + result.confidence_note : 'No'),
        'Category Applied   : ' + (gs.nil(existingCategory) ? 'Yes (field was empty)' : 'No (existing value "' + existingCategory + '" preserved)')
    ];
    caseGr.work_notes = noteLines.join('\n');
    changed = true;

    if (changed) {
        caseGr.setWorkflow(false);   // suppress re-triggering other BRs on this admin update
        caseGr.update();
        gs.info('x_2145749_qc AI Triage: Case ' + current.getUniqueValue() +
                ' updated — urgency=' + result.urgency_score +
                ', category=' + result.category +
                ', manual_review=' + result.needs_manual_review);
    }

})(current, previous);
